import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function Example(props) {
    var done = React.useState(false), result = React.useRef(null), area = React.useRef(null), resetFocus = React.useRef(false);
    React.useEffect(function () {
        if (done[0])
            result.current.focus();
        else if (resetFocus.current) {
            area.current.querySelector('button').focus();
            resetFocus.current = false;
        }
    }, [done[0]]);
    function reset() { resetFocus.current = true; done[1](false); }
