    {'Снова показать пустое состояние'}
    </S.DsButton>
    </div> : <S.DsEmptyState icon={props.icon} headingLevel={'h4'} title={props.title} description={props.description} tone={props.tone} size={props.small ? 'sm' : 'md'} action={<S.DsButton tone={props.primary ? 'primary' : 'secondary'} size={props.small ? 'sm' : 'md'} onClick={function () { done[1](true); }}>
    {props.action}
    </S.DsButton>}/>}
    </div>
    </div>;
}
function App() {
    return <div className="dsemptystate-example">
    <style>{exampleStyles}</style>
    <Example id={'filtered'} heading={'Ничего не найдено'} icon={'filter_alt'} title={'Нет объектов по заданным фильтрам'} description={'Попробуйте изменить условия или сбросьте фильтры.'} action={'Сбросить фильтры'} result={'Фильтры сброшены. Найдено 12 объектов.'}/>
