import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function RetryExample() {
    var phase = React.useState('error'), attempts = React.useState(0), timer = React.useRef(null), area = React.useRef(null), result = React.useRef(null), restore = React.useRef(false);
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    React.useEffect(function () {
        if (phase[0] === 'ready')
            result.current.focus();
        else if (restore.current) {
            area.current.querySelector('button').focus();
            restore.current = false;
        }
    }, [phase[0]]);
    function retry() {
        if (phase[0] !== 'error')
            return;
        phase[1]('loading');
        attempts[1](function (n) { return n + 1; });
        timer.current = setTimeout(function () { phase[1]('ready'); }, 1200);
    }
    function reset() { restore.current = true; phase[1]('error'); attempts[1](0); }
    return <div className={"demo-stack"}>
    <div className={'narrow'} ref={area}>
    {phase[0] === 'ready' ? <div className={'result'} tabIndex={-1} ref={result}>
    <p>
    {'Соединение восстановлено. Объекты загружены.'}
    </p>
    <S.DsButton tone={'ghost'} size={'sm'} onClick={reset}>
    {'Снова показать пустое состояние'}
    </S.DsButton>
    </div> : <S.DsEmptyState headingLevel={'h4'} icon={'cloud_off'} tone={'danger'} size={'sm'} title={'Не удалось загрузить объекты'} description={'Нет связи с сервисом. Повторите запрос.'} action={<S.DsButton tone={'secondary'} size={'sm'} loading={phase[0] === 'loading'} onClick={retry}>
    {'Повторить запрос'}
    </S.DsButton>}/>}
    <p className={'caption'} role={'status'}>
    {phase[0] === 'loading' ? 'Повторный запрос выполняется. Дождитесь ответа.' : ''}
    </p>
    <p className={'caption'}>
    {'Попыток: ' + attempts[0]}
    </p>
    </div>
    </div>;
}
function App() {
    return <div className="dsemptystate-example">
    <style>{exampleStyles}</style>
    <RetryExample />
    </div>;
}

const exampleStyles = ".dsemptystate-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsemptystate-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsemptystate-example p{margin:0}\n.dsemptystate-example .result{padding:16px;overflow-wrap:anywhere}\n.dsemptystate-example .result p{margin:0 0 12px}\n.dsemptystate-example .result:focus-visible{outline:var(--ds-focus-width) solid var(--ds-focus-color);outline-offset:var(--ds-focus-offset)}\n.dsemptystate-example .caption{font:var(--ds-type-caption);color:var(--ds-fg-muted);text-align:center;margin:8px 0 0}\n.dsemptystate-example .caption:empty{display:none}\n.dsemptystate-example .narrow{width:100%;max-width:360px;margin-inline:auto}";

