import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function TwoActions() {
    var help = React.useState(false), result = React.useState(false), area = React.useRef(null), link = React.useRef(null);
    React.useEffect(function () {
        if (help[0])
            area.current.focus();
    }, [help[0]]);
    return <div className={"demo-stack"}>
    <div className={'narrow'}>
    <S.DsEmptyState icon={null} headingLevel={'h4'} announcement={'polite'} title={result[0] ? 'Период изменён' : 'За выбранный период нет маршрутов'} description={result[0] ? 'Выбраны последние 7 дней. Найдено 3 маршрута.' : 'Маршруты хранятся 90 дней. Выберите более короткий период или прочитайте, как работает хранение данных.'} action={<S.DsButton tone={'primary'} onClick={function () { result[1](!result[0]); }}>
    {result[0] ? 'Вернуть исходный период' : 'Выбрать последние 7 дней'}
    </S.DsButton>} secondary={<a ref={link} href={'#retention-help'} className={'text-link'} onClick={function (e) { e.preventDefault(); help[1](true); }}>
    {'О хранении маршрутов'}
    </a>}/>
    </div>
    <div id={'retention-help'} ref={area} tabIndex={-1} className={'result'} hidden={!help[0] && !result[0]}>
    <p>
    {help[0] ? 'Маршруты старше 90 дней удаляются. Экспортируйте нужные данные до окончания срока хранения.' : 'Три маршрута доступны для просмотра.'}
    </p>
    {help[0] ? <S.DsButton tone={'ghost'} size={'sm'} onClick={function () { help[1](false); link.current.focus(); }}>
    {'Закрыть пояснение'}
    </S.DsButton> : null}
    </div>
    </div>;
}
function App() {
    return <div className="dsemptystate-example">
    <style>{exampleStyles}</style>
    <TwoActions />
    </div>;
}

